{"point":{"id":"source_evidence","title":"Repository Evidence and Navigation","rationale":"Source resolution follows an explicit diagram source binding instead of assuming a project has one repository. Mapping joins resolve selected diagram nodes to captured source ranges, retaining provenance and hashes. Corpus and language-service adapters provide file access and definition lookup, while CodePanel translates these joins into the browsing experience.","sourcePaths":["application/core/source/diagramSource.ts","application/core/source/projectSource.ts","application/core/corpus/corpusAccess.ts","infrastructure/core/corpus/corpus.ts","infrastructure/core/persistence/repositoryRegistry.ts","infrastructure/core/language-services/projectLanguageService.ts","domain/mapping/code-panel/codePanel.ts","src/features/mapping/code-panel/CodePanel.tsx"],"relationships":[{"pointId":"diagrams","label":"resolves source bindings, mappings, and captured evidence","kind":"dependency"},{"pointId":"persistence","label":"reads registered sources and published representations","kind":"dependency"}]},"sources":[{"path":"application/core/source/diagramSource.ts","text":"import { createStoredDiagram } from '../../../domain/core/diagrams/diagramRevisionStore';
import { diagramSource, validateDiagram, type Diagram, type DiagramSourceBinding } from '../../../domain/core/diagrams/diagram';

import { sceneFromRevision } from '../../../domain/core/diagrams/projectDiagramCanvas';
import type { CorpusAccess } from '../corpus/corpusAccess';
import { ApplicationError } from '../errors';
import type { DiagramRepository } from '../ports/diagramRepository';
export interface DiagramSourceReference { projectId: string; representationId?: string; revisionId?: string; contentId?: string; sourceId?: string }
/** Resolve a saved diagram/revision, or an unambiguous registered source. Never infer a repository from Project. */
export async function resolveDiagramSource(store: Pick<DiagramRepository,'loadProject'|'projectCatalogs'>, ref: DiagramSourceReference, corpus?: CorpusAccess, liveDiagram?: Diagram) {
  const project = await store.loadProject();
  if (!project || project.id !== ref.projectId) throw new ApplicationError('conflict','Diagram belongs to another project');
  const catalog = ref.representationId ? await store.projectCatalogs.loadRepresentationCatalog(project.id) : undefined;
  let diagram: Diagram | undefined;
  const representation = ref.representationId ? catalog!.representations[ref.representationId] : undefined;
  const revisionId = ref.revisionId ?? representation?.currentRevisionId;
  if (ref.representationId && (!representation || !revisionId || !representation.revisionIds.includes(revisionId))) throw new Error('Unknown diagram revision');
  if (liveDiagram) {
    validateDiagram(liveDiagram);
    if (ref.contentId && liveDiagram.id !== ref.contentId) throw new Error('Live diagram identity does not match selection');
    diagram = liveDiagram;
  } else if (ref.representationId) {
    const scene = sceneFromRevision(catalog!.revisions[revisionId!]);
    const candidates = Object.values(scene.contents).filter(d => ref.contentId ? d.id === ref.contentId : !!d.sourceContext.binding);
    if (candidates.length !== 1) throw new Error('Select an individual diagram with contentId');
    diagram = candidates[0];
  } else {
    const bindings = new Map<string,DiagramSourceBinding>();
    const register = (binding: DiagramSourceBinding) => {
      const old = bindings.get(binding.sourceId);
      if (old && (old.corpus.root !== binding.corpus.root || old.corpus.kind !== binding.corpus.kind || old.repositoryIdentity !== binding.repositoryIdentity)) throw new Error('Conflicting diagram source identity');
      bindings.set(binding.sourceId,binding);
    };
    for (const binding of await store.projectCatalogs.loadDiagramSourceBindings(project.id)) {
      if (binding && (!ref.sourceId || binding.sourceId === ref.sourceId)) register(binding);
    }
    for (const binding of project.sources ?? []) {
      if (binding && (!ref.sourceId || binding.sourceId === ref.sourceId)) register(binding);
    }
    if (bindings.size !== 1) throw new Error('A valid diagram sourceId is required; the project has no single repository');
    diagram = createStoredDiagram({id:'source-query',revision:0,ascii:'Source',source:[...bindings.values()][0]}).diagram;
  }
  if (ref.sourceId && diagram.sourceContext.binding?.sourceId !== ref.sourceId) throw new Error('Source does not belong to diagram');
  const query = diagramSource(diagram);
  const binding = () => {
    const result = query.context.binding;
    if (!result) throw new Error('This diagram has no source repository');
    return result;
  };
  return { ...query, diagram, binding,
    readText: (file: string) => { const source=binding(); if (!corpus) throw new Error('Source access unavailable'); return corpus.provider(source.corpus).readDocumentText(source.corpus,file); },
    listFiles: (directory: string) => { const source=binding(); if (!corpus) throw new Error('Source access unavailable'); return corpus.provider(source.corpus).listDirectory(source.corpus,directory); }
  };
}
"},{"path":"application/core/source/projectSource.ts","text":"import { createHash } from 'node:crypto';
import type { SourcePosition } from '../../../domain/core/source/sourceNavigation';
import type { CorpusAccess } from '../corpus/corpusAccess';
import { ApplicationError } from '../errors';
import type { DiagramRepository } from '../ports/diagramRepository';
import { resolveDiagramSource, type DiagramSourceReference } from './diagramSource';
import type { LanguageService } from './languageService';

export class ProjectSourceService {
  constructor(
    private readonly projects: Pick<DiagramRepository, 'loadProject' | 'projectCatalogs'>,
    private readonly corpus: CorpusAccess,
    private readonly language?: LanguageService
  ) { }

  async files(projectId: string | null, directory: string, sourceId?: string) {
    const source = await resolveDiagramSource(this.projects, {projectId: projectId ?? '', sourceId}, this.corpus);
    return source.listFiles(directory);
  }

  ensureDefinitionsEnabled(): void {
    if (!this.language) throw new ApplicationError('lsp-disabled', 'Definition lookup is disabled. Start the server with --lsp to enable it.');
  }

  async definitions(input: DiagramSourceReference & { path: string; position: SourcePosition; sourceSha256: string }, signal: AbortSignal) {
    if (!this.language) throw new ApplicationError('lsp-disabled', 'Definition lookup is disabled. Start the server with --lsp to enable it.');
    const source = await resolveDiagramSource(this.projects, input, this.corpus);
    return this.language.definitions(source.binding().corpus, input.path, input.position, input.sourceSha256, signal);
  }

  async source(projectId: string | null, sourcePath: string | null, sourceId?: string) {
    if (!sourcePath) throw new ApplicationError('invalid-input', 'Source path is required');
    const resolved = await resolveDiagramSource(this.projects, {projectId: projectId ?? '', sourceId}, this.corpus);
    const source = await resolved.readText(sourcePath);
    if (source.includes('\0')) throw new ApplicationError('binary-source', 'This is a binary file. The source pane displays text files.');
    return {
      path: sourcePath, startLine: 1, lines: source.split(/\r?\n/),
      sourceSha256: createHash('sha256').update(source).digest('hex'), lspEnabled: Boolean(this.language)
    };
  }
}
"},{"path":"application/core/corpus/corpusAccess.ts","text":"import type { BuiltInDomainProfileId, CorpusBinding, CorpusProvider } from "../../../domain/core/profiles/domainProfile";
import type { RepositoryLocation } from "./location";

export interface ReadableCorpusProvider extends CorpusProvider {
  readDocumentBytes(binding: CorpusBinding, path: string): Promise<Buffer>;
  readDocumentText(binding: CorpusBinding, path: string): Promise<string>;
  readDocumentLines(binding: CorpusBinding, path: string): Promise<string[]>;
}

export interface CorpusAccess {
  provider(binding: CorpusBinding): ReadableCorpusProvider;
  readDocumentLines(binding: CorpusBinding, path: string): Promise<string[]>;
  discover(inputPath: string, profile: BuiltInDomainProfileId): Promise<RepositoryLocation>;
}
"},{"path":"infrastructure/core/corpus/corpus.ts","text":"import {
  lstat,
  readdir,
  readFile,
  realpath,
  stat
} from "node:fs/promises";
import path from "node:path";
import type { CorpusBinding, CorpusDirectoryListing, CorpusProvider } from "../../../domain/core/profiles/domainProfile";
import type { SourceRange } from "../../../domain/core/records/domain";

function relativeSegments(value: string, label: string): string[] {
  if (value.includes("\0") || value.includes("\\")) {
    throw new Error(`${label} path is invalid`);
  }
  if (path.posix.isAbsolute(value) || path.win32.isAbsolute(value)) {
    throw new Error(`${label} path must be relative`);
  }
  const segments = value === "" ? [] : value.split("/");
  if (segments.some((segment) => !segment || segment === "." || segment === "..")) {
    throw new Error(`${label} path is invalid`);
  }
  return segments;
}

async function canonicalBindingRoot(binding: CorpusBinding, expectedKind: CorpusBinding["kind"]): Promise<string> {
  if (binding.kind !== expectedKind) {
    throw new Error(`corpus provider ${expectedKind} cannot read ${binding.kind}`);
  }
  const root = await realpath(binding.root).catch(() => null);
  if (!root || !(await stat(root)).isDirectory()) {
    throw new Error(`corpus root is not a directory: ${path.resolve(binding.root)}`);
  }
  return root;
}

async function resolveWithoutSymlinks(
  root: string,
  relativePath: string,
  label: string
): Promise<string> {
  const segments = relativeSegments(relativePath, label);
  let resolved = root;
  for (const segment of segments) {
    resolved = path.join(resolved, segment);
    const info = await lstat(resolved).catch(() => null);
    if (!info) throw new Error(`unknown ${label} path: ${relativePath}`);
    if (info.isSymbolicLink()) {
      throw new Error(label === "corpus directory"
        ? "symbolic-link directories cannot be traversed"
        : "symbolic-link corpus file paths cannot be traversed");
    }
  }
  if (resolved !== root && !resolved.startsWith(`${root}${path.sep}`)) {
    throw new Error(`${label} path escapes corpus root`);
  }
  return resolved;
}

class FilesystemCorpusProvider implements CorpusProvider {
  constructor(readonly kind: CorpusBinding["kind"]) { }

  async listDirectory(
    binding: CorpusBinding,
    directory: string
  ): Promise<CorpusDirectoryListing> {
    const root = await canonicalBindingRoot(binding, this.kind);
    const directoryPath = await resolveWithoutSymlinks(root, directory, "corpus directory");
    if (!(await stat(directoryPath)).isDirectory()) {
      throw new Error(`corpus path is not a directory: ${directory}`);
    }
    const entries = (await readdir(directoryPath, { withFileTypes: true }))
      .filter((entry) => entry.name !== ".git")
      .map((entry) => ({
        path: path.relative(root, path.join(directoryPath, entry.name)).split(path.sep).join("/"),
        name: entry.name,
        kind: entry.isDirectory() && !entry.isSymbolicLink()
          ? "directory" as const
          : "file" as const
      }))
      .sort((left, right) => (
        (left.kind === right.kind ? 0 : left.kind === "directory" ? -1 : 1)
        || left.name.localeCompare(right.name, undefined, { sensitivity: "base" })
        || left.path.localeCompare(right.path)
      ));
    return { directory: relativeSegments(directory, "corpus directory").join("/"), entries };
  }

  async readLines(binding: CorpusBinding, range: SourceRange): Promise<string[]> {
    if (!Number.isInteger(range.startLine) || !Number.isInteger(range.endLine)
      || range.startLine < 1 || range.endLine < range.startLine) {
      throw new Error(`invalid evidence range for ${range.path}`);
    }
    const lines = await this.readDocumentLines(binding, range.path);
    return lines.slice(range.startLine - 1, Math.min(range.endLine, lines.length));
  }

  async readDocumentLines(binding: CorpusBinding, relativePath: string): Promise<string[]> {
    return (await this.readDocumentText(binding, relativePath)).split(/\r?\n/);
  }

  async readDocumentText(binding: CorpusBinding, relativePath: string): Promise<string> {
    return (await this.readDocumentBytes(binding, relativePath)).toString("utf8");
  }

  async readDocumentBytes(binding: CorpusBinding, relativePath: string): Promise<Buffer> {
    const root = await canonicalBindingRoot(binding, this.kind);
    const filePath = await resolveWithoutSymlinks(root, relativePath, "corpus file");
    if (!(await stat(filePath)).isFile()) throw new Error(`corpus path is not a file: ${relativePath}`);
    return readFile(filePath);
  }
}

export type ReadableCorpusProvider = CorpusProvider & {
  readDocumentBytes(binding: CorpusBinding, relativePath: string): Promise<Buffer>;
  readDocumentText(binding: CorpusBinding, relativePath: string): Promise<string>;
  readDocumentLines(binding: CorpusBinding, relativePath: string): Promise<string[]>;
};

const providers: Record<CorpusBinding["kind"], ReadableCorpusProvider> = {
  "git-worktree": new FilesystemCorpusProvider("git-worktree"),
  "filesystem-documents": new FilesystemCorpusProvider("filesystem-documents")
};

export function corpusProvider(binding: CorpusBinding): ReadableCorpusProvider {
  return providers[binding.kind];
}

export async function readCorpusDocumentLines(
  binding: CorpusBinding,
  relativePath: string
): Promise<string[]> {
  return corpusProvider(binding).readDocumentLines(binding, relativePath);
}
"},{"path":"infrastructure/core/persistence/repositoryRegistry.ts","text":"import { captureGitHunks } from './repositoryHunks';
import type { RepositoryContext } from '../../../domain/core/repositories/repository';
import path from 'node:path';
import { createHash } from 'node:crypto';
import type { RepositoryRegistry } from '../../../application/core/ports/repositoryRegistry';
import type { Repository } from '../../../domain/core/repositories/repository';
import { repositoryContextSchema } from '../../../domain/core/repositories/repository';
import type { ProjectRecord } from '../../../domain/core/records/domain';
import { discoverRepository, execFileAsync, readJsonIfExists, writeJsonAtomic } from './shared';

const queues = new Map<string, Promise<unknown>>();
export class GitRepositoryRegistry implements RepositoryRegistry {
  private readonly file: string;
  constructor(storeRoot: string, private readonly checkoutRoot: string) { this.file = path.join(storeRoot, 'project.json'); }
  private async serial<T>(run: () => Promise<T>): Promise<T> {
    const next = (queues.get(this.file) ?? Promise.resolve()).catch(() => {}).then(run);
    queues.set(this.file, next);
    try { return await next; } finally { if (queues.get(this.file) === next) queues.delete(this.file); }
  }
  private async project() {
    const project = await readJsonIfExists<ProjectRecord>(this.file);
    if (!project) throw Error('Project is not initialized');
    return project;
  }
  private async discover(root: string, name?: string): Promise<Repository> {
    const location = await discoverRepository(root);
    return { id: `repo-${createHash('sha256').update(location.repositoryIdentity).digest('hex').slice(0, 24)}`,
      name: name?.trim() || path.basename(location.checkoutRoot), identity: location.repositoryIdentity, checkoutRoots: [location.checkoutRoot] };
  }
  /** Backfill only repository identities we can actually discover. Non-Git projects stay unassigned. */
  async initialize() {
    return this.serial(async () => {
      const project = await this.project();
      if (project.repositories !== undefined) return project;
      const repositories: Repository[] = [];
      const roots = new Set([this.checkoutRoot, ...(project.sources ?? []).filter(s => s.corpus.kind === 'git-worktree').map(s => s.corpus.root)]);
      for (const root of roots) {
        const repository = await this.discover(root).catch(() => undefined);
        if (!repository) continue;
        const prior = repositories.find(r => r.id === repository.id);
        if (prior) prior.checkoutRoots = [...new Set([...prior.checkoutRoots, ...repository.checkoutRoots])];
        else repositories.push(repository);
      }
      const next = { ...project, repositories };
      await writeJsonAtomic(this.file, next);
      return next;
    });
  }
  async list() { return (await this.initialize()).repositories ?? []; }
  async register(input: { path: string; name?: string }) {
    const found = await this.discover(input.path, input.name);
    await this.initialize();
    return this.serial(async () => {
      const project = await this.project(), repositories = [...(project.repositories ?? [])];
      const index = repositories.findIndex(repository => repository.id === found.id), prior = repositories[index];
      const repository = { ...found, name: input.name?.trim() || prior?.name || found.name,
        checkoutRoots: [...new Set([...(prior?.checkoutRoots ?? []), ...found.checkoutRoots])] };
      if (index < 0) repositories.push(repository); else repositories[index] = repository;
      await writeJsonAtomic(this.file, { ...project, repositories, updatedAt: new Date().toISOString() });
      return repository;
    });
  }
  private async availableRoot(repository: Repository) {
    let root: string | undefined;
    // A saved worktree may have been removed since the repository was registered.
    // The current checkout is also usable, but only for the same Git repository.
    for (const candidate of new Set([...repository.checkoutRoots, this.checkoutRoot])) {
      const location = await discoverRepository(candidate).catch(() => undefined);
      if (location?.repositoryIdentity === repository.identity) { root = location.checkoutRoot; break; }
    }
    if (!root) throw Error('Repository checkout is unavailable');
    return root;
  }
  async resolveCheckoutRoot(repositoryId: string) {
    const repository = (await this.list()).find(repository => repository.id === repositoryId);
    if (!repository) throw Error('Unknown repositoryId');
    return this.availableRoot(repository);
  }
  async captureHunks(context: RepositoryContext) {
    repositoryContextSchema.parse(context);
    const repository = (await this.list()).find(repo => repo.id === context.repositoryId);
    if (!repository) throw Error('Unknown repositoryId');
    return captureGitHunks(await this.availableRoot(repository), context);
  }
  async resolveContext(input: { repositoryId?: string; commits?: string[]; head?: string; comparisonBase?: string | null }) {
    const repositories = await this.list();
    const repository = input.repositoryId ? repositories.find(r => r.id === input.repositoryId) : repositories.length === 1 ? repositories[0] : undefined;
    if (!repository) throw Error('Specify a registered repositoryId for this ChangeSession');
    const root = await this.availableRoot(repository);
    const resolved = new Map<string, string>();
    const resolve = async (ref: string) => {
      if (resolved.has(ref)) return resolved.get(ref)!;
      try {
        const sha = (await execFileAsync('git', ['-C', root!, 'rev-parse', '--verify', '--end-of-options', `${ref}^{commit}`], { encoding: 'utf8' })).stdout.trim();
        resolved.set(ref, sha);
        return sha;
      } catch { throw Error(`Unknown commit in repository ${repository.name}: ${ref}`); }
    };
    const head = await resolve(input.head ?? 'HEAD');
    const commits = new Set<string>();
    for (const ref of input.commits ?? []) commits.add(await resolve(ref));
    return repositoryContextSchema.parse({ repositoryId: repository.id, head, commits: [...commits],
      ...(input.comparisonBase !== undefined ? { comparisonBase: input.comparisonBase === null ? null : await resolve(input.comparisonBase) } : {}) });
  }
}
"},{"path":"infrastructure/core/language-services/projectLanguageService.ts","text":"import { spawn } from 'node:child_process';
import { createHash } from 'node:crypto';
import { realpath } from 'node:fs/promises';
import { createRequire } from 'node:module';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { CancellationTokenSource, createMessageConnection, StreamMessageReader, StreamMessageWriter } from 'vscode-jsonrpc/node.js';
import type { CorpusBinding } from '../../../domain/core/profiles/domainProfile';
import { isRepositoryFilePath, supportsDefinitions, type SourceDefinitions, type SourceLocation, type SourcePosition } from '../../../domain/core/source/sourceNavigation';
import { corpusProvider } from '../corpus/corpus';
const require = createRequire(import.meta.url);
const liveSessions = new Set<LanguageSession>();
let signalHandlersInstalled = false;
function registerSession(session: LanguageSession) {
  liveSessions.add(session);
  if (signalHandlersInstalled) return;
  signalHandlersInstalled = true;
  for (const [signal, code] of [['SIGTERM', 143], ['SIGINT', 130]] as const) {
    process.once(signal, () => { for (const session of liveSessions) session.dispose(); process.exit(code); });
  }
}

class LanguageSession {
  private readonly child;
  private readonly rpc;
  private readonly ready: Promise<void>;
  private queue: Promise<unknown> = Promise.resolve();
  private idle?: ReturnType<typeof setTimeout>;
  dead = false;
  constructor(readonly root: string) {
    const cli = path.join(path.dirname(require.resolve('typescript-language-server/package.json')), 'lib/cli.mjs');
    this.child = spawn(process.execPath, [cli, '--stdio', '--log-level', '1'], { cwd: root, stdio: ['pipe', 'pipe', 'pipe'], detached: process.platform !== 'win32' });
    this.child.stderr.resume();
    this.rpc = createMessageConnection(new StreamMessageReader(this.child.stdout), new StreamMessageWriter(this.child.stdin));
    this.rpc.onRequest('workspace/configuration', (params: { items: unknown[] }) => params.items.map(() => ({})));
    this.rpc.onRequest('client/registerCapability', () => null);
    this.rpc.onRequest('workspace/applyEdit', () => ({ applied: false }));
    this.rpc.onError(() => this.dispose());
    this.child.on('error', () => this.dispose());
    this.child.on('exit', () => this.dispose());
    this.rpc.listen();
    registerSession(this);
    this.ready = this.bounded(async () => {
      const capabilities = await this.rpc.sendRequest<{ capabilities: { definitionProvider?: unknown; positionEncoding?: string } }>('initialize', {
        processId: process.pid, rootUri: pathToFileURL(root).href,
        capabilities: { general: { positionEncodings: ['utf-16'] }, textDocument: { definition: { linkSupport: true } } },
        workspaceFolders: [{ uri: pathToFileURL(root).href, name: path.basename(root) }],
        initializationOptions: { tsserver: { useSyntaxServer: 'never', path: require.resolve('typescript/lib/tsserver.js') } }
      });
      if (!capabilities.capabilities.definitionProvider || (capabilities.capabilities.positionEncoding && capabilities.capabilities.positionEncoding !== 'utf-16')) {
        throw new Error('Language server does not support UTF-16 definition lookup');
      }
      await this.rpc.sendNotification('initialized', {});
    });
    // Initialization may fail before the first queued request attaches.
    void this.ready.then(() => {
      this.scheduleIdle();
    }, () => this.dispose());
  }
  private scheduleIdle() {
    clearTimeout(this.idle);
    if (this.dead) return;
    this.idle = setTimeout(() => this.dispose(), 5 * 60_000);
    this.idle.unref();
  }
  private async bounded<T>(run: () => Promise<T>): Promise<T> {
    let timer: ReturnType<typeof setTimeout> | undefined;
    try {
      return await Promise.race([run(), new Promise<never>((_, reject) => {
        timer = setTimeout(() => { reject(new Error('Language server timed out; try again')); this.dispose(); }, 20000);
      })]);
    } finally { clearTimeout(timer); }
  }
  lookup(file: string, text: string, position: SourcePosition, signal?: AbortSignal): Promise<unknown> {
    const run = async () => {
      clearTimeout(this.idle);
      try {
        await this.ready;
        if (this.dead) throw new Error('Language server stopped; try again');
        signal?.throwIfAborted();
        const uri = pathToFileURL(path.join(this.root, file)).href;
        const cancellation = new CancellationTokenSource();
        const abort = () => cancellation.cancel();
        signal?.addEventListener('abort', abort, { once: true });
        try {
          await this.rpc.sendNotification('textDocument/didOpen', {
            textDocument: {
              uri, version: 1, text,
              languageId: /\.tsx$/i.test(file) ? 'typescriptreact' : /\.jsx$/i.test(file) ? 'javascriptreact' : /\.[cm]?ts$/i.test(file) ? 'typescript' : 'javascript'
            }
          });
          return await this.bounded(() => this.rpc.sendRequest('textDocument/definition', { textDocument: { uri }, position }, cancellation.token));
        } finally {
          signal?.removeEventListener('abort', abort);
          cancellation.dispose();
          if (!this.dead) await this.rpc.sendNotification('textDocument/didClose', { textDocument: { uri } });
        }
      } finally { this.scheduleIdle(); }
    };
    const result = this.queue.then(run);
    this.queue = result.catch(() => undefined);
    return result;
  }
  dispose() {
    if (this.dead) return;
    this.dead = true;
    liveSessions.delete(this);
    clearTimeout(this.idle);
    this.rpc.dispose();
    if (this.child.pid) {
      try { process.kill(process.platform === 'win32' ? this.child.pid : -this.child.pid, 'SIGTERM'); } catch { /* already exited */ }
    }
  }
}

/** One lazy TS/JS session per checkout, shared by every pane. */
export class ProjectLanguageService {
  private sessions = new Map<string, LanguageSession>();
  private disposed = false;
  private readonly exit = () => this.dispose();
  constructor() { process.once('exit', this.exit); }
  async definitions(binding: CorpusBinding, file: string, position: SourcePosition, sourceSha256: string, signal?: AbortSignal): Promise<SourceDefinitions> {
    if (this.disposed) throw new Error('Language service is stopped');
    signal?.throwIfAborted();
    if (!isRepositoryFilePath(file) || !supportsDefinitions(file)) throw new Error('Definitions are supported for TypeScript and JavaScript files');
    if (!position || !Number.isInteger(position.line) || position.line < 0 || !Number.isInteger(position.character) || position.character < 0) throw new Error('Invalid source position');
    const text = await corpusProvider(binding).readDocumentText(binding, file);
    if (createHash('sha256').update(text).digest('hex') !== sourceSha256) throw new Error('Source changed on disk. Reload the file before looking up definitions.');
    const line = text.split(/\r?\n/)[position.line];
    if (line === undefined || position.character > line.length) throw new Error('Source position is outside the file');
    const root = await realpath(binding.root);
    if (this.disposed) throw new Error('Language service is stopped');
    signal?.throwIfAborted();
    let session = this.sessions.get(root);
    if (!session || session.dead) { session = new LanguageSession(root); this.sessions.set(root, session); }
    const result = await session.lookup(file, text, position, signal);
    signal?.throwIfAborted();
    const locations: SourceLocation[] = [];
    let outsideRoot = 0;
    const seen = new Set<string>();
    for (const item of (Array.isArray(result) ? result : result ? [result] : []) as Array<{ uri?: string; targetUri?: string; range?: SourceLocation['range']; targetSelectionRange?: SourceLocation['range'] }>) {
      const uri = item.targetUri ?? item.uri;
      if (!uri?.startsWith('file:')) { outsideRoot++; continue; }
      const relative = path.relative(root, fileURLToPath(uri)).split(path.sep).join('/');
      if (!isRepositoryFilePath(relative)) { outsideRoot++; continue; }
      const location = { path: relative, range: item.targetSelectionRange ?? item.range };
      const key = JSON.stringify(location);
      if (!seen.has(key)) { seen.add(key); locations.push(location); }
    }
    return { locations, outsideRoot };
  }
  dispose() { this.disposed = true; for (const session of this.sessions.values()) session.dispose(); this.sessions.clear(); process.removeListener('exit', this.exit); }
}
"},{"path":"domain/mapping/code-panel/codePanel.ts","text":"import { resolveNodeResources } from '../../core/diagrams/diagramResourceMappings';
import { diagramSource, type Diagram } from '../../core/diagrams/diagram';
import type { DiagramContentNode } from '../../core/diagrams/diagramContent';
import { diagramContentNodes } from '../../core/diagrams/diagramContentNodes';
import { mappingContentNodeId } from '../../core/presentation/diagramText';
import { sha256 } from '../../core/sha256';
import type { CodeRepoReference } from '../../core/source/codeRepoService';

/** Mapped source coordinates are inclusive, one-based lines, unlike LSP positions. */
export interface SourceRangeReference {
  repo: CodeRepoReference;
  path: string;
  startLine: number;
  endLine: number;
  rangeSha256: string;
}
export type MappedResource = { type: 'source-range'; target: SourceRangeReference };
export type MappedResourceType = MappedResource['type'];
export const DEFAULT_MAPPED_RESOURCE_TYPE: MappedResourceType = 'source-range';
export interface DiagramContext { diagram: Diagram; projectId: string }
export interface MappingOrigin {
  selectedNodeId: string; selectedLabel: string;
  mappedNodeId: string; mappedLabel: string; mappingId: string;
}
export interface ResolvedMapping { resource: MappedResource; origins: MappingOrigin[] }
export interface PanelContent {
  mappedResourceType: MappedResourceType;
  diagramId: string; revisionId: string; contentHash: string;
  selectedNodeIds: string[]; unmappedNodeIds: string[];
  items: ResolvedMapping[];
}
export interface SourceDisplayRange { startLine: number; endLine: number; items: ResolvedMapping[] }
export interface SourceDisplayFile {
  id: string; repo: CodeRepoReference; path: string; ranges: SourceDisplayRange[];
}

function sourceRangeIndex({ diagram, projectId }: DiagramContext): Map<string, ResolvedMapping[]> {
  const index = new Map<string, ResolvedMapping[]>();
  if (diagram.sourceContext.contentHash !== diagram.content.asciiSha256) throw new Error('Diagram mappings are stale');
  for (const { mapping, entity, range, binding } of diagramSource(diagram).entries()) {
    const nodeId = mappingContentNodeId(diagram.content, mapping);
    if (!nodeId || !entity || !range) continue;
    const list = index.get(nodeId) ?? [];
    list.push({ resource: { type: 'source-range', target: {
      repo: { projectId, sourceId: entity.sourceId ?? binding?.sourceId ?? '' },
      path: range.path, startLine: range.startLine, endLine: range.endLine,
      rangeSha256: sha256(range.originalLines.join('\n')),
    } }, origins: [{ selectedNodeId: '', selectedLabel: '', mappedNodeId: nodeId, mappedLabel: '', mappingId: mapping.id }] });
    index.set(nodeId, list);
  }
  return index;
}
export function sourceResourceIdentity(resource: MappedResource): string {
  const t = resource.target;
  return JSON.stringify([resource.type, t.repo.projectId, t.repo.sourceId, t.path, t.startLine, t.endLine, t.rangeSha256]);
}
/** Preserve diagram order, starting another section when files change or source lines go backwards. */
export function buildSourceRangeDisplayModel(items: readonly ResolvedMapping[]): SourceDisplayFile[] {
  const files: SourceDisplayFile[] = [];
  for (const item of items) {
    const t = item.resource.target;
    let file = files.at(-1);
    if (!file || file.path !== t.path || file.repo.projectId !== t.repo.projectId || file.repo.sourceId !== t.repo.sourceId
      || t.startLine < file.ranges.at(-1)!.startLine) {
      file = { id: sourceResourceIdentity(item.resource), repo: t.repo, path: t.path, ranges: [] };
      files.push(file);
    }
    const previous = file.ranges.at(-1);
    if (previous && t.startLine <= previous.endLine) {
      previous.endLine = Math.max(previous.endLine, t.endLine); previous.items.push(item);
    } else file.ranges.push({ startLine: t.startLine, endLine: t.endLine, items: [item] });
  }
  return files;
}
/** Domain handlers contain no React or file I/O. Renderers are registered in the UI. */
export const mappedResourceHandlers = {
  'source-range': { index: sourceRangeIndex, identity: sourceResourceIdentity, buildDisplayModel: buildSourceRangeDisplayModel },
} satisfies Record<MappedResourceType, unknown>;

export function resolveSelectedNodes(context: DiagramContext, selected: readonly DiagramContentNode[],
  mappedResourceType: MappedResourceType = DEFAULT_MAPPED_RESOURCE_TYPE) {
  const direct = mappedResourceHandlers[mappedResourceType].index(context);
  const { matches, unmappedNodeIds } = resolveNodeResources(diagramContentNodes(context.diagram.content), selected.map(node => node.id), direct);
  const results: ResolvedMapping[] = matches.flatMap(({ selectedNode, mappedNode, resources }) => resources.map(item => ({
    ...item, origins: item.origins.map(origin => ({ ...origin, selectedNodeId: selectedNode.id,
      selectedLabel: selectedNode.label, mappedNodeId: mappedNode.id, mappedLabel: mappedNode.label }))
  })));
  return { results, unmappedNodeIds };
}
export function handleNodeSelect(context: DiagramContext, nodes: readonly DiagramContentNode[],
  mappedResourceType: MappedResourceType = DEFAULT_MAPPED_RESOURCE_TYPE): PanelContent {
  nodes = [...nodes].sort((a, b) => a.line - b.line || a.startColumn - b.startColumn);
  const { results, unmappedNodeIds } = resolveSelectedNodes(context, nodes, mappedResourceType);
  const combined = new Map<string, ResolvedMapping>();
  for (const result of results) {
    const key = mappedResourceHandlers[mappedResourceType].identity(result.resource);
    const prior = combined.get(key);
    if (prior) prior.origins.push(...result.origins); else combined.set(key, { ...result, origins: [...result.origins] });
  }
  return { mappedResourceType, diagramId: context.diagram.id, revisionId: context.diagram.content.revisionId,
    contentHash: context.diagram.content.asciiSha256, selectedNodeIds: [...new Set(nodes.map(n => n.id))],
    unmappedNodeIds, items: [...combined.values()] };
}
"},{"path":"src/features/mapping/code-panel/CodePanel.tsx","text":"import { useContext, useEffect, useLayoutEffect, useMemo, useRef, useState, type ComponentType } from 'react';
import { sha256 } from '../../../../domain/core/sha256';
import { mappedResourceHandlers, type MappedResourceType, type PanelContent, type SourceDisplayFile } from '../../../../domain/mapping/code-panel/codePanel';
import type { CodePanelPaneContent, SourceCodePaneContent } from '../../../../domain/mapping/workspace/displayModel';
import type { CompactedSource } from '../../../../domain/core/records/domain';
import type { CodeRepoFile } from '../../../../domain/core/source/codeRepoService';
import type { SourceLocation, SourcePosition } from '../../../../domain/core/source/sourceNavigation';
import { supportsDefinitions } from '../../../../domain/core/source/sourceNavigation';
import { SourceCodeView } from '../../../shared/source/SourceCodeView';
import { SourceCodePane } from '../source-pane/SourceCodePane';
import { SourcePaneDocumentContext, SourcePaneViewStateContext, SourcePaneDocumentActiveContext } from '../source-pane/SourcePaneViewStateContext';
import { useMappingServices } from '../services/MappingServices';

const presentation = { syntaxHighlighting: 'code', markdownRendering: 'source', wrap: false, sourceCompaction: true } as const;
function SourceRangeSections({ file, onOpen, hoveredNode }: { file: SourceDisplayFile;
  onOpen: (file: SourceDisplayFile, location?: SourceLocation) => void; hoveredNode?: string }) {
  const { codeRepo } = useMappingServices();
  const [loaded, setLoaded] = useState<CodeRepoFile>();
  const [error, setError] = useState('');
  const [attempt, setAttempt] = useState(0);
  const loadedAttempt = useRef(0);
  const [definitions, setDefinitions] = useState<SourceLocation[]>([]);
  const [message, setMessage] = useState('');
  const definitionRequest = useRef<AbortController | undefined>(undefined);
  useEffect(() => {
    const controller = new AbortController(); setLoaded(undefined); setError('');
    const reload = loadedAttempt.current !== attempt; loadedAttempt.current = attempt;
    void codeRepo.readFile(file.repo, file.path, { signal: controller.signal, reload }).then(result => {
      if (!controller.signal.aborted) setLoaded(result);
    }, error => { if (!controller.signal.aborted) setError(String(error.message ?? error)); });
    return () => { controller.abort(); definitionRequest.current?.abort(); };
  }, [codeRepo, file.id, attempt]);
  const lines = useMemo(() => loaded?.text.replace(/\r\n?/g, '\n').split('\n') ?? [], [loaded]);
  const stale = Boolean(loaded && file.ranges.some(range => range.items.some(({ resource: { target } }) =>
    target.endLine > lines.length || sha256(lines.slice(target.startLine - 1, target.endLine).join('\n')) !== target.rangeSha256)));
  // The existing folding renderer now folds gaps, leaving every mapped range visible.
  const compactedSource = useMemo<CompactedSource>(() => {
    const sections: CompactedSource['sections'] = [];
    let start = 1;
    for (const range of [...file.ranges, { startLine: lines.length + 1, endLine: lines.length }]) {
      if (start < range.startLine) sections.push({ kind: 'collapsed-comment', startLine: start, endLine: range.startLine - 1,
        comment: `${range.startLine - start} lines hidden` });
      start = range.endLine + 1;
    }
    return { level: 'medium', sections };
  }, [file.ranges, lines.length]);
  const preview = useMemo(() => ({ path: file.path, startLine: 1, lines }), [file.path, lines]);
  const sourceRange = useMemo(() => ({ path: file.path, startLine: file.ranges[0]?.startLine ?? 1,
    endLine: file.ranges.at(-1)?.endLine ?? 1, compactedSource }), [file.path, file.ranges, compactedSource]);
  const lookup = async (position: SourcePosition) => {
    if (!loaded) return;
    definitionRequest.current?.abort(); const controller = new AbortController(); definitionRequest.current = controller;
    setMessage('Finding definition…'); setDefinitions([]);
    try {
      const result = await codeRepo.definitions(file.repo, { path: file.path, position, sourceSha256: loaded.sha256 }, { signal: controller.signal });
      if (controller.signal.aborted) return;
      if (result.locations.length === 1) { setMessage(''); onOpen(file, result.locations[0]); }
      else { setDefinitions(result.locations); setMessage(result.locations.length ? 'Choose a definition:' : 'No definition found in this repository.'); }
    } catch (error) { if (!controller.signal.aborted) setMessage(String(error)); }
  };
  const root = useRef<HTMLElement>(null);
  const highlightedNodes = useRef<HTMLElement[]>([]);
  const clearHighlights = () => {
    highlightedNodes.current.forEach(el => delete el.dataset.codePanelHighlight);
    highlightedNodes.current = [];
  };
  useEffect(() => clearHighlights, []);
  const highlightNodes = (ids: string[]) => {
    clearHighlights();
    const stage = root.current?.closest('.mapping-document-view') ?? root.current?.closest('[data-diagram-canvas]') ?? root.current?.closest('.mapping-poc-graph-stage');
    stage?.querySelectorAll<HTMLElement>('[data-content-node-id]').forEach(el => {
      if (ids.includes(el.dataset.contentNodeId!)) {
        el.dataset.codePanelHighlight = 'true';
        highlightedNodes.current.push(el);
      }
    });
  };
  const annotations = useMemo(() => file.ranges.map(range => ({ startLine: range.startLine,
    content: <span className="code-panel-origins" data-panel-node-highlight={range.items.some(item => item.origins.some(origin => origin.selectedNodeId === hoveredNode)) || undefined}
      onMouseEnter={() => highlightNodes(range.items.flatMap(item => item.origins.map(origin => origin.selectedNodeId)))} onMouseLeave={() => highlightNodes([])}>
      {[...new Map(range.items.flatMap(item => item.origins).map(origin => [origin.selectedNodeId, origin])).values()].map(origin =>
        <span key={origin.selectedNodeId}>{origin.selectedLabel}{origin.selectedNodeId !== origin.mappedNodeId ? ` — via ${origin.mappedLabel}` : ''}</span>)}
    </span> })), [file.ranges, hoveredNode]);
  return <section ref={root} className="code-panel-file" data-code-panel-file={file.path} data-resource-loading={!loaded && !error}>
    <header><strong>{file.path}</strong><small title={file.repo.sourceId || 'Default repository'}>{file.repo.sourceId || 'Default repository'}</small>
      <button type="button" onClick={() => onOpen(file)}>Browse source</button>
      <button type="button" onClick={() => setAttempt(n => n + 1)} aria-label={`Reload ${file.path}`}>↻</button></header>
    {error ? <p role="alert">{error} <button onClick={() => setAttempt(n => n + 1)}>Retry</button></p>
      : !loaded ? <p role="status">Loading source…</p>
      : stale ? <p role="status">Stale mapping: the source no longer matches this mapped block. Update the mapping to view its code.</p> : <>
        {message && <p role="status">{message}{definitions.map((location, i) => <button key={i} onClick={() => onOpen(file, location)}>{location.path}:{(location.range?.start.line ?? 0) + 1}</button>)}</p>}
        <SourceCodeView preview={preview} range={sourceRange}
          compacted foldPresentation="gap" highlightedRanges={file.ranges} lineAnnotations={annotations}
          presentation={presentation} onGoToDefinition={loaded.lspEnabled && supportsDefinitions(file.path) ? lookup : undefined} deferOffscreen />
      </>}
  </section>;
}
interface ResourceRendererProps {
  items: PanelContent['items'];
  hoveredNode?: string;
  onOpenSource: (file: SourceDisplayFile, location?: SourceLocation) => void;
}
/** Each renderer owns its resource-specific display model; the panel only dispatches by type. */
function SourceResources({ items, hoveredNode, onOpenSource }: ResourceRendererProps) {
  const files = useMemo(() => mappedResourceHandlers['source-range'].buildDisplayModel(items), [items]);
  return files.map(file => <SourceRangeSections key={file.id} file={file} hoveredNode={hoveredNode} onOpen={onOpenSource} />);
}
const resourceRenderers = { 'source-range': SourceResources } satisfies Record<MappedResourceType, ComponentType<ResourceRendererProps>>;
export function CodePanel({ id, content }: { id: string; content: CodePanelPaneContent }) {
  const root = useRef<HTMLDivElement>(null);
  const [navigation, setNavigation] = useState<{ file: SourceCodePaneContent; location?: SourceLocation }>();
  const [hoveredNode, setHoveredNode] = useState<string>();
  const viewState = useContext(SourcePaneViewStateContext), documentId = useContext(SourcePaneDocumentContext);
  const active = useContext(SourcePaneDocumentActiveContext);
  const scroll = useMemo(() => viewState?.bind(documentId, id, '@code-panel', content.scroll), [viewState, documentId, id, content.scroll]);
  useLayoutEffect(() => {
    const el = root.current; if (!el || !active) return;
    const position = scroll?.read();
    let restoring = Boolean(position);
    const restore = () => {
      if (!restoring || !position) return;
      el.scrollTop = position.top; el.scrollLeft = position.left;
      if (!el.querySelector('[data-resource-loading="true"]')) restoring = false;
    };
    restore();
    // Source reads finish after mount. Restore again when their sections acquire height.
    const observer = new ResizeObserver(restore);
    if (el.firstElementChild) observer.observe(el.firstElementChild);
    const stopRestoring = () => { restoring = false; };
    el.addEventListener('wheel', stopRestoring, { passive: true });
    const disconnect = scroll?.connect(() => restoring ? position : el.getClientRects().length ? { top: el.scrollTop, left: el.scrollLeft } : undefined);
    return () => { observer.disconnect(); el.removeEventListener('wheel', stopRestoring); disconnect?.(); };
  }, [scroll, active, navigation !== undefined]);
  useEffect(() => { setNavigation(undefined); }, [content.panel]);
  useEffect(() => {
    const stage = root.current?.closest('.mapping-document-view') ?? root.current?.closest('[data-diagram-canvas]') ?? root.current?.closest('.mapping-poc-graph-stage');
    const hover = (event: Event) => setHoveredNode((event.target as Element).closest<HTMLElement>('[data-content-node-id]')?.dataset.contentNodeId);
    stage?.addEventListener('pointerover', hover); return () => stage?.removeEventListener('pointerover', hover);
  }, []);
  const Renderer = resourceRenderers[content.panel.mappedResourceType];
  return <div className="code-panel" data-code-panel={content.panel.mappedResourceType}>
    <div className="code-panel-summary">{content.panel.selectedNodeIds.length} selected nodes · {content.panel.items.length} mapped resources
      {navigation && <button onClick={() => setNavigation(undefined)}>Back to mapped ranges</button>}</div>
    {navigation ? <SourceCodePane id={`${id}:browse`} content={navigation.file} initialLocation={navigation.location}
      onChange={(_id, patch) => setNavigation(current => current && ({ ...current, file: { ...current.file, ...patch } }))} />
      : <div ref={root} className="code-panel-content" onScroll={event => scroll?.write({ top: event.currentTarget.scrollTop, left: event.currentTarget.scrollLeft })}>
        <div className="code-panel-resources">
        {!!content.panel.unmappedNodeIds.length && <p role="status">{content.panel.unmappedNodeIds.length} selected nodes have no mapping.</p>}
        <Renderer items={content.panel.items} hoveredNode={hoveredNode} onOpenSource={(file, location) => setNavigation({
          file: { kind: 'source-code', projectId: file.repo.projectId, sourceId: file.repo.sourceId, sourceFile: location?.path ?? file.path,
            files: [], showCompactions: false, rangeIndex: 0 }, location })} />
        </div>
      </div>}
  </div>;
}
